const filters=document.querySelectorAll('.filter'),cards=[...document.querySelectorAll('.card')],search=document.querySelector('.search'),empty=document.querySelector('#empty');let category='all';function update(){let q=search.value.trim().toLowerCase(),n=0;cards.forEach(c=>{let show=(category==='all'||c.dataset.category.includes(category))&&c.innerText.toLowerCase().includes(q);c.style.display=show?'':'none';if(show)n++});empty.style.display=cards.length&&!n?'block':'none'}filters.forEach(b=>b.addEventListener('click',()=>{category=b.dataset.filter;filters.forEach(x=>x.classList.toggle('active',x===b));update()}));search.addEventListener('input',update);;
(()=>{const dialog=document.getElementById('payment-dialog'),title=document.getElementById('selected-book'),contact=document.getElementById('telegram-order'),status=document.getElementById('copy-status');document.querySelectorAll('.order-button').forEach(b=>b.addEventListener('click',()=>{const card=b.closest('.card'),name=card.querySelector('h3').textContent;title.textContent=name+' · displayed price $9.99 (confirm USDT amount before paying)';contact.href='https://t.me/Ismail1top?text='+encodeURIComponent('Hello, I would like to ask about '+name+'. Please confirm availability, the price in USDT, and delivery.');status.textContent='';dialog.showModal()}));document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});document.getElementById('copy-address').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.getElementById('wallet-address').textContent.trim());status.textContent='Address copied. Check the network and address before sending.'}catch(e){status.textContent='Copy unavailable. Select the address above to copy it.'}})})();;
(()=>{const reduce=window.matchMedia('(prefers-reduced-motion: reduce)');const strip=document.querySelector('.strip .wrap');if(strip){const group=document.createElement('div');group.className='marquee-group';while(strip.firstChild)group.appendChild(strip.firstChild);const copy=group.cloneNode(true);copy.setAttribute('aria-hidden','true');const track=document.createElement('div');track.className='marquee-track';track.append(group,copy);strip.append(track)}if(!reduce.matches&&'IntersectionObserver'in window){document.documentElement.classList.add('js-motion');const items=document.querySelectorAll('.section-head,.filters,.card,.feature-grid > div,.about > div');const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');observer.unobserve(e.target)}})},{threshold:.08,rootMargin:'0px 0px -20px 0px'});items.forEach((el,i)=>{el.classList.add('reveal-on-scroll');if(el.classList.contains('card'))el.style.setProperty('--reveal-delay',(i%4)*70+'ms');observer.observe(el)})}const bar=document.querySelector('.scroll-progress');let pending=false;function sync(){const max=document.documentElement.scrollHeight-innerHeight;bar.style.transform='scaleX('+(max>0?scrollY/max:0)+')';pending=false}addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(sync)}},{passive:true});sync()})();;
(()=>{const video=document.querySelector('.hero-chart-video');if(video&&!matchMedia('(prefers-reduced-motion: reduce)').matches){video.src=video.dataset.src;video.play().catch(()=>{});}})();
